\pset tuples_only on
\pset format unaligned
select 'CATALOG_INVENTORY_JSON:' || jsonb_build_object(
 'columns',(select jsonb_agg(jsonb_build_object('key',table_schema||'.'||table_name||'.'||column_name,'hash',md5(to_jsonb(s)::text)) order by table_schema,table_name,ordinal_position) from (select table_schema,table_name,ordinal_position,column_name,data_type,udt_schema,udt_name,is_nullable,column_default from information_schema.columns where table_schema in ('public','app','corporate_gate_private'))s),
 'policies',(select jsonb_agg(jsonb_build_object('key',schemaname||'.'||tablename||'.'||policyname,'hash',md5(to_jsonb(s)::text)) order by schemaname,tablename,policyname) from (select schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname in ('public','app','corporate_gate_private','storage'))s),
 'functions',(select jsonb_agg(jsonb_build_object('key',signature,'hash',md5(definition)) order by signature) from (select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' as signature,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app','corporate_gate_private') and p.prokind='f')s),
 'triggers',(select jsonb_agg(jsonb_build_object('key',key,'hash',md5(definition)) order by key) from (select n.nspname||'.'||c.relname||'.'||t.tgname as key,pg_get_triggerdef(t.oid) as definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app','corporate_gate_private') and not t.tgisinternal)s),
 'constraints',(select jsonb_agg(jsonb_build_object('key',schema_name||'.'||table_name||'.'||constraint_name,'hash',md5(to_jsonb(s)::text)) order by schema_name,table_name,constraint_name) from (select n.nspname as schema_name,c.relname as table_name,k.conname as constraint_name,pg_get_constraintdef(k.oid) as definition from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app','corporate_gate_private'))s)
)::text;
